window.KHO_DATA_L5_MITHUAT = [
{"lop":5,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS chọn được từ khoá phù hợp và tìm được tư liệu đúng yếu tố tạo hình cần.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm tư liệu cho chủ đề của mình trong kho ảnh và bảo tàng số GV chỉ định; GV hướng dẫn cách chọn từ khoá theo yếu tố tạo hình như chấm, nét, hình, khối, màu, đậm nhạt thay vì tìm chung chung, và cách đọc phần chú thích để biết ảnh của ai.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS lập phiếu tư liệu gồm ba hình đã chọn, mỗi hình ghi yếu tố tạo hình nổi bật và nguồn ảnh.\n⚠ (Miền 4: An toàn) Chỉ tìm trong các trang GV đã chỉ định, không tự vào trang lạ, không tải tệp không rõ nguồn; ảnh đưa vào phiếu phải ghi tên tác giả hoặc tên trang, thiếu nguồn thì không dùng.","hs":"- HS chọn được từ khoá phù hợp và tìm được tư liệu đúng yếu tố tạo hình cần.\n- HS lập được phiếu tư liệu có ghi nguồn đầy đủ."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS phác được nhiều phương án bố cục bằng ứng dụng vẽ và biết hoàn tác khi cần.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS dùng ứng dụng vẽ đơn giản trên máy của lớp để phác vài phương án bố cục cho sản phẩm: thử đổi vị trí mảng chính, đổi tỉ lệ, hoàn tác khi chưa ưng; vẽ trên máy cho phép thử nhiều phương án trong thời gian ngắn, việc mà phác trên giấy tốn nhiều thời gian hơn.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS chọn một phương án, nói rõ vì sao bỏ các phương án còn lại rồi chuyển sang thể hiện sản phẩm bằng chất liệu thật.\n⚠ (Miền 4: An toàn) HS lưu bản phác vào thư mục mang tên mình, không mở và sửa bài của bạn; bản phác trên máy chỉ là bước chuẩn bị, sản phẩm cuối cùng vẫn do HS thể hiện bằng tay.","hs":"- HS phác được nhiều phương án bố cục bằng ứng dụng vẽ và biết hoàn tác khi cần.\n- HS chọn và bảo vệ được phương án bố cục của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 1: Yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thích cái đẹp, có ý thức tìm tòi, sáng tạo trong học tập.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS hoàn thiện được phần giới thiệu sản phẩm trên trang trưng bày của lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề yếu tố tạo hình trong thực hành, sáng tạo theo chủ đề vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chụp sản phẩm và đưa vào trang trưng bày của lớp kèm tên tác phẩm, tên tác giả và một câu nêu yếu tố tạo hình mình đã dùng làm điểm nhấn.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS nhận xét sản phẩm của bạn theo đúng tiêu chí đã học về yếu tố tạo hình nổi bật, bố cục và màu sắc, nói lời góp ý xây dựng thay vì khen chung chung.\n⚠ (Miền 4: An toàn) Ghi đủ tên tác giả cho từng sản phẩm và nguồn cho mọi tư liệu tham khảo; trang trưng bày chia sẻ trong lớp, muốn đưa ra ngoài phải hỏi ý kiến các bạn có sản phẩm trong đó.","hs":"- HS hoàn thiện được phần giới thiệu sản phẩm trên trang trưng bày của lớp.\n- HS nhận xét bạn theo tiêu chí cụ thể, có góp ý xây dựng."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 1, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.\n4. Tích hợp\n- Năng lực số 1.2 CB2 (Đánh giá dữ liệu, thông tin và nội dung số): HS đối chiếu được hai nguồn tư liệu trước khi thể hiện nhân vật lịch sử.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm hiểu về một anh hùng dân tộc qua tư liệu số ở trang của bảo tàng và thư viện tỉnh: tượng đài, tranh chân dung, hiện vật; đối chiếu ít nhất hai nguồn về niên đại và chi tiết trang phục, vũ khí trước khi đưa vào bài vẽ.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi vào phiếu tên nhân vật, chi tiết tạo hình đặc trưng và tên hai nguồn đã đối chiếu.\n⚠ (Miền 4: An toàn) Thông tin lịch sử phải lấy từ bảo tàng, sách giáo khoa hoặc trang của cơ quan nhà nước; nhiều hình vẽ nhân vật lịch sử trên mạng là do người ta tưởng tượng hoặc do máy tạo, không đúng sử liệu nên không dùng làm căn cứ.","hs":"- HS đối chiếu được hai nguồn tư liệu trước khi thể hiện nhân vật lịch sử.\n- HS ghi được nguồn và chi tiết tạo hình đặc trưng của nhân vật."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nắm được tư thế và tỉ lệ dáng nhân vật nhờ xem tượng từ nhiều góc.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem tượng đài anh hùng dân tộc chụp từ nhiều góc và ở chế độ xoay ba chiều nếu bảo tàng số có sẵn; nhờ đó thấy được tư thế, hướng nhìn và tỉ lệ dáng người mà một bức ảnh chính diện không diễn tả hết.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS phác dáng nhân vật theo tư thế mình chọn, dùng ảnh chụp từ góc tương ứng để kiểm tra lại tỉ lệ đầu, thân, chân rồi sửa chỗ chưa cân đối.\n⚠ (Miền 4: An toàn) HS thao tác trên máy dùng chung, mở đúng trang GV giao và đóng lại sau khi dùng; hình ảnh tượng đài là tư liệu di sản nên khi dùng phải ghi rõ tên tác phẩm và tác giả.","hs":"- HS nắm được tư thế và tỉ lệ dáng nhân vật nhờ xem tượng từ nhiều góc.\n- HS tự kiểm tra và sửa được tỉ lệ trong bài phác của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 2: Hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về truyền thống anh hùng và lịch sử dân tộc.\n- Chăm chỉ, có trách nhiệm khi hoàn thành nhiệm vụ học tập.\n4. Tích hợp\n- Năng lực số 2.1 CB2 (Tương tác thông qua công nghệ số): HS trình bày được tác phẩm và phân biệt rõ phần dựa vào tư liệu với phần sáng tạo riêng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề hình tượng anh hùng dân tộc trong mĩ thuật tạo hình Việt Nam vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS giới thiệu tác phẩm của mình trước lớp: nhân vật là ai, vì sao em chọn tư thế đó, chi tiết nào em lấy từ tư liệu và chi tiết nào là ý tưởng riêng.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp lập trang trưng bày có ảnh tác phẩm, tên tác giả và danh mục nguồn tư liệu đã sử dụng đặt ở cuối trang.\n⚠ (Miền 4: An toàn) Nói về nhân vật lịch sử phải trung thực với tư liệu, không thêm chi tiết không có thật; ghi đủ nguồn cho ảnh tư liệu; trang trưng bày chỉ chia sẻ trong phạm vi nhà trường.","hs":"- HS trình bày được tác phẩm và phân biệt rõ phần dựa vào tư liệu với phần sáng tạo riêng.\n- HS lập được danh mục nguồn tư liệu cho trang trưng bày."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 2, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 3: Gia đình (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.3 CB2 (Quản lí dữ liệu, thông tin và nội dung số): HS phân tích được cách sắp xếp nhân vật trong tranh đề tài gia đình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề gia đình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề gia đình.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem bộ tranh đề tài gia đình của các hoạ sĩ Việt Nam trên bảo tàng số, phóng to để phân tích cách sắp xếp nhân vật: ai đứng trước, ai đứng sau, khoảng cách giữa các nhân vật nói lên tình cảm gì.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi lại một cách sắp xếp nhân vật mình muốn học hỏi cùng tên bức tranh và tên hoạ sĩ.\n⚠ (Miền 4: An toàn) Tranh của hoạ sĩ thuộc bản quyền của tác giả và nơi lưu giữ; HS chỉ xem để học cách sắp xếp, không sao chép nguyên bố cục rồi nhận là của mình; khi tham khảo phải ghi tên tranh và tác giả.","hs":"- HS phân tích được cách sắp xếp nhân vật trong tranh đề tài gia đình.\n- HS ghi đúng tên tranh, tên hoạ sĩ khi tham khảo."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 3: Gia đình (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS thử được nhiều bố cục nhân vật bằng cách kéo thả hình khối trên máy.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề gia đình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề gia đình).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS dùng ứng dụng vẽ hoặc phần mềm trình chiếu tạo các hình khối đơn giản đại diện cho từng nhân vật rồi kéo thả thử nhiều cách sắp xếp; nhìn ngay được bố cục nào cân đối, bố cục nào chen chúc mà không phải tẩy xoá trên giấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chốt một bố cục, ghi lại lí do và chuyển sang phác hình nhân vật trên giấy.\n⚠ (Miền 4: An toàn) HS lưu tệp vào thư mục của mình và đặt tên tệp có tên mình để không nhầm với bài của bạn; không đưa ảnh chụp gia đình mình lên máy dùng chung của lớp.","hs":"- HS thử được nhiều bố cục nhân vật bằng cách kéo thả hình khối trên máy.\n- HS chọn và giải thích được bố cục cuối cùng của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 3: Gia đình (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề gia đình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề gia đình (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 3: Gia đình (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu thương, gắn bó với gia đình; trân trọng tình cảm gia đình.\n- Chăm chỉ, cẩn thận, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 2.5 CB2 (Nghi thức giao tiếp trong môi trường số): HS chia sẻ và lắng nghe về đề tài gia đình một cách tế nhị.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề gia đình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề gia đình vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS giới thiệu tác phẩm về gia đình ở mức mình muốn chia sẻ và lắng nghe bạn; GV hướng dẫn cách nhận xét tế nhị vì mỗi gia đình một hoàn cảnh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp lập trang trưng bày chỉ gồm ảnh tác phẩm và tên tác giả, không kèm thông tin riêng về gia đình.\n⚠ (Miền 4: An toàn) Không hỏi tò mò về hoàn cảnh gia đình bạn, không kể lại chuyện riêng của bạn cho người khác; trang trưng bày không ghi địa chỉ, nghề nghiệp, số điện thoại của người thân và chỉ chiếu trong lớp.","hs":"- HS chia sẻ và lắng nghe về đề tài gia đình một cách tế nhị.\n- HS nhận ra thông tin nào không nên đưa lên sản phẩm được chia sẻ."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 3, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS phân tích được dáng người trong hoạt động nhờ dừng hình clip.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những hoạt động yêu thích ở trường em.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề những hoạt động yêu thích ở trường em.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem lại kho ảnh và clip các hoạt động của trường trong năm như hội khoẻ, văn nghệ, lao động, câu lạc bộ; dừng hình ở những khoảnh khắc động để phân tích dáng người đang chạy, đang nhảy, đang cổ vũ.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS chọn một hoạt động, liệt kê các nhân vật và đồ vật cần có rồi phác sơ đồ bố cục trước khi vẽ.\n⚠ (Miền 4: An toàn) Kho ảnh của trường chỉ dùng trong nhà trường; bạn nào không muốn hình mình được sử dụng thì phải bỏ ảnh đó ra; không cắt ghép ảnh của bạn theo cách gây cười, chế giễu.","hs":"- HS phân tích được dáng người trong hoạt động nhờ dừng hình clip.\n- HS lập được sơ đồ bố cục cho bài vẽ của mình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những hoạt động yêu thích ở trường em.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề những hoạt động yêu thích ở trường em).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những hoạt động yêu thích ở trường em.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề những hoạt động yêu thích ở trường em (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 4: Những hoạt động yêu thích ở trường em (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu trường lớp, thầy cô, bạn bè; tích cực tham gia hoạt động chung.\n- Chăm chỉ, đoàn kết, giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS viết được chú thích nêu rõ phần sáng tạo thêm so với ảnh tư liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những hoạt động yêu thích ở trường em.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề những hoạt động yêu thích ở trường em vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp làm trang trưng bày Những hoạt động yêu thích ở trường em gồm tranh của HS đặt cạnh ảnh tư liệu tương ứng; HS viết chú thích cho biết mình đã thêm bớt gì so với ảnh.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS bình chọn tác phẩm diễn tả được không khí sôi nổi nhất và nêu căn cứ bình chọn, tránh bình chọn theo cảm tình bạn bè.\n⚠ (Miền 4: An toàn) Ảnh tư liệu có mặt bạn chỉ được dùng khi bạn đồng ý; trang trưng bày chia sẻ trong trường, muốn đăng lên trang thông tin của trường phải được nhà trường cho phép.","hs":"- HS viết được chú thích nêu rõ phần sáng tạo thêm so với ảnh tư liệu.\n- HS bình chọn dựa trên tiêu chí chứ không theo cảm tình."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 4, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"Đánh giá cuối học kì I","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong học kì để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình (hình, mảng, màu sắc, đậm nhạt, không gian) phù hợp nội dung.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.","dodung":"- Giáo viên: yêu cầu thực hành, tiêu chí đánh giá; thiết bị trình chiếu học liệu số.\n- Học sinh: đồ dùng học tập môn Mĩ thuật, giấy vẽ, màu vẽ, chất liệu đã chuẩn bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết đánh giá cuối học kì I.\n- GV công bố yêu cầu và tiêu chí đánh giá sản phẩm.","hs":"- HS lắng nghe, nắm yêu cầu và tiêu chí."},{"ten":"2. Thực hành, đánh giá","gv":"- GV tổ chức cho HS làm bài thực hành: tạo một sản phẩm mĩ thuật theo chủ đề đã học trong học kì.\n- GV bao quát lớp, hỗ trợ khi cần, bảo đảm HS làm bài độc lập.","hs":"- HS thực hành tạo sản phẩm theo yêu cầu.\n- HS vận dụng kiến thức, kĩ năng đã học."},{"ten":"3. Trưng bày, nhận xét","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm.\n- GV nhận xét, đánh giá theo tiêu chí; ghi nhận sự tiến bộ của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS tự đánh giá và nhận xét sản phẩm của bạn."},{"ten":"4. Vận dụng - Dặn dò","gv":"- GV tổng kết tiết đánh giá, tuyên dương HS.\n- GV dặn dò nội dung học tập của học kì II.","hs":"- HS lắng nghe, ghi nhớ và chuẩn bị cho học kì II."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Đánh giá cuối học kì I"},
{"lop":5,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 1.2 CB2 (Đánh giá dữ liệu, thông tin và nội dung số): HS kiểm chứng được câu chuyện qua hai nguồn trước khi chọn làm đề tài.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm trên báo dành cho thiếu nhi và trang của cơ quan nhà nước những câu chuyện về việc làm tử tế của người bình thường, đối chiếu hai nguồn để chắc chắn câu chuyện có thật trước khi lấy làm đề tài.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi vào phiếu câu chuyện, nhân vật, nguồn tin và chi tiết nào có thể chuyển thành hình ảnh trong tranh.\n⚠ (Miền 4: An toàn) Trên mạng có nhiều câu chuyện cảm động được dựng lên hoặc do máy viết ra để câu người xem; HS phải kiểm tra ở nguồn chính thống trước khi tin và trước khi kể lại cho bạn.","hs":"- HS kiểm chứng được câu chuyện qua hai nguồn trước khi chọn làm đề tài.\n- HS ghi được phiếu tư liệu có nguồn rõ ràng."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 5.2 CB2 (Xác định nhu cầu và giải pháp công nghệ): HS ghi và phác được dáng đặc trưng của nghề nhờ dừng hình clip.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề những việc làm bình dị mà cao quý trong cuộc sống).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS xem clip tư liệu về công việc mình chọn, dừng hình để ghi lại dáng đặc trưng của nghề như dáng cúi của người quét đường, dáng với tay của người thợ điện, cùng các đồ vật đi kèm, sau đó phác dáng theo ghi chép.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS đối chiếu bản phác với ảnh dừng hình để chỉnh lại tỉ lệ và tư thế cho đúng đặc trưng của nghề.\n⚠ (Miền 4: An toàn) HS mở đúng clip GV cung cấp, không bấm sang clip gợi ý bên cạnh; nếu muốn chụp ảnh người lao động ngoài đời làm tư liệu thì phải xin phép người ấy trước.","hs":"- HS ghi và phác được dáng đặc trưng của nghề nhờ dừng hình clip.\n- HS tự chỉnh sửa được tỉ lệ, tư thế theo tư liệu."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề những việc làm bình dị mà cao quý trong cuộc sống (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 5: Những việc làm bình dị mà cao quý trong cuộc sống (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Trân trọng những việc làm tốt đẹp, tử tế trong cuộc sống; có ý thức làm việc tốt.\n- Chăm chỉ, nhân ái, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 2.2 CB2 (Chia sẻ thông tin qua công nghệ số): HS viết được câu chuyện ngắn trung thực đi kèm tranh của mình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề những việc làm bình dị mà cao quý trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề những việc làm bình dị mà cao quý trong cuộc sống vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp lập trang trưng bày kèm mỗi tranh một câu chuyện ngắn về việc làm tử tế và gửi tới các lớp trong trường để lan toả; HS tập viết câu chuyện ngắn gọn, trung thực.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi rõ nguồn của câu chuyện và tên tác giả tranh ở cuối mỗi phần.\n⚠ (Miền 4: An toàn) Chỉ kể lại câu chuyện đã kiểm chứng, không thêm chi tiết cho cảm động; nếu câu chuyện về một người cụ thể ở địa phương thì phải hỏi ý kiến người ấy hoặc gia đình trước khi nêu tên.","hs":"- HS viết được câu chuyện ngắn trung thực đi kèm tranh của mình.\n- HS ghi đủ nguồn và tên tác giả trên sản phẩm chung của lớp."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 5, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS xác định được ba lớp cảnh gần, trung, xa nhờ xem địa hình từ nhiều góc.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề cảnh sắc quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề cảnh sắc quê hương.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS dùng bản đồ số và ảnh toàn cảnh xem lại một vùng của quê mình từ nhiều góc, nhận ra lớp cảnh gần, cảnh trung và cảnh xa; góc nhìn từ trên cao giúp HS hiểu bố cục của cảnh mà đứng dưới đất không hình dung được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi vào phiếu tư liệu ba lớp cảnh mình sẽ đưa vào tranh và nguồn của ảnh tham khảo.\n⚠ (Miền 4: An toàn) Chỉ tra cứu trong ứng dụng bản đồ GV chỉ định; không đánh dấu và không chia sẻ vị trí nhà mình hay nhà bạn; ảnh vệ tinh và ảnh toàn cảnh có bản quyền nên khi dùng phải ghi nguồn.","hs":"- HS xác định được ba lớp cảnh gần, trung, xa nhờ xem địa hình từ nhiều góc.\n- HS ghi được nguồn cho ảnh tham khảo."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề cảnh sắc quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề cảnh sắc quê hương).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề cảnh sắc quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề cảnh sắc quê hương (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 6: Cảnh sắc quê hương (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về cảnh sắc, vẻ đẹp của quê hương, đất nước.\n- Chăm chỉ, cẩn thận, có ý thức giữ gìn cảnh quan.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS hoàn thiện được phần thông tin cho tranh của mình trong triển lãm.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề cảnh sắc quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề cảnh sắc quê hương vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp dựng trang triển lãm Cảnh sắc quê hương sắp xếp tranh theo vùng, mỗi tranh ghi tên địa danh, tên tác giả và chất liệu.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đóng vai người xem triển lãm, đặt cho tác giả một câu hỏi về cách thể hiện lớp cảnh xa gần và tác giả trả lời.\n⚠ (Miền 4: An toàn) Ghi đủ tên tác giả và nguồn ảnh tham khảo; trang triển lãm chia sẻ trong trường, muốn đăng công khai phải được nhà trường và cha mẹ đồng ý.","hs":"- HS hoàn thiện được phần thông tin cho tranh của mình trong triển lãm.\n- HS đặt và trả lời được câu hỏi về cách thể hiện xa gần."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 6, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 1.2 CB2 (Đánh giá dữ liệu, thông tin và nội dung số): HS đối chiếu được hai nguồn và gọi đúng tên dân tộc, vùng miền.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề việt Nam đất nước, con người.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề việt Nam đất nước, con người.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS tìm tư liệu về trang phục, lễ hội, kiến trúc của một vùng miền trên trang của bảo tàng và cổng thông tin địa phương, đối chiếu ít nhất hai nguồn để tránh nhầm lẫn trang phục giữa các dân tộc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS lập phiếu tư liệu ghi tên vùng miền, dân tộc, chi tiết đặc trưng và nguồn của từng thông tin.\n⚠ (Miền 4: An toàn) Trang phục và hoa văn của mỗi dân tộc gắn với văn hoá của cộng đồng ấy nên vẽ sai hoặc gán nhầm cho dân tộc khác là thiếu tôn trọng; ảnh tư liệu phải ghi rõ nguồn, không dùng ảnh do máy tạo làm căn cứ vì máy hay trộn lẫn đặc điểm các dân tộc.","hs":"- HS đối chiếu được hai nguồn và gọi đúng tên dân tộc, vùng miền.\n- HS lập được phiếu tư liệu ghi rõ nguồn."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS dựng được dải hoa văn đối xứng bằng lệnh sao chép và lật hình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề việt Nam đất nước, con người.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề việt Nam đất nước, con người).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS dùng ứng dụng vẽ tạo một hoạ tiết đặc trưng của vùng miền mình chọn rồi dùng lệnh sao chép và lật hình để dựng thành dải hoa văn đối xứng; máy giúp thấy ngay hiệu quả của sự lặp lại và đối xứng trước khi vẽ tay.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV nhập tên một loại hoa văn dân tộc vào công cụ tạo hình bằng trí tuệ nhân tạo cho máy sinh vài mẫu; HS đối chiếu với ảnh tư liệu thật, chỉ ra chỗ máy vẽ sai và giải thích vì sao máy dễ nhầm hoa văn của các dân tộc với nhau.\n⚠ (Miền 4: An toàn) Mẫu do máy sinh chỉ dùng để so sánh và phê phán, không đưa vào sản phẩm rồi giới thiệu là hoa văn của một dân tộc vì làm vậy là truyền đi thông tin sai về văn hoá của họ; GV thao tác công cụ, HS không dùng tài khoản riêng.","hs":"- HS dựng được dải hoa văn đối xứng bằng lệnh sao chép và lật hình.\n- HS chỉ ra được chỗ sai của mẫu hoa văn do máy sinh và nêu được lí do."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề việt Nam đất nước, con người.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề việt Nam đất nước, con người (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 7: Việt Nam đất nước, con người (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu quý, tự hào về đất nước, con người và bản sắc văn hoá Việt Nam.\n- Chăm chỉ, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 2.2 CB2 (Chia sẻ thông tin qua công nghệ số): HS thuyết minh được về vùng miền mình thể hiện dựa trên tư liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề việt Nam đất nước, con người.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề việt Nam đất nước, con người vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp dựng trang trưng bày Việt Nam đất nước, con người xếp theo vùng miền; mỗi HS thuyết minh ngắn về vùng miền mình thể hiện cho các bạn nghe.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi ở cuối trang danh mục nguồn tư liệu và tên tác giả của từng tác phẩm.\n⚠ (Miền 4: An toàn) Thuyết minh phải đúng với tư liệu, không nói theo cảm tính về phong tục của dân tộc khác; ghi đủ nguồn; chỉ chia sẻ trong phạm vi nhà trường.","hs":"- HS thuyết minh được về vùng miền mình thể hiện dựa trên tư liệu.\n- HS lập được danh mục nguồn cho trang trưng bày của lớp."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 7, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình, hình ảnh, chất liệu liên quan đến chủ đề.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 1.1 CB2 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS giải thích được ý nghĩa của một biểu tượng hoà bình trong mĩ thuật.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề vì một thế giới hoà bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 5 và tư liệu GV chuẩn bị thêm về chủ đề vì một thế giới hoà bình.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem các tác phẩm mĩ thuật Việt Nam và thế giới về đề tài hoà bình như chim bồ câu, vòng tay, cánh đồng, trẻ em, tìm hiểu vì sao mỗi hình ảnh trở thành biểu tượng và đọc chú thích để biết tác giả, năm sáng tác.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một biểu tượng, ghi lại ý nghĩa của nó và tên tác phẩm đã dùng biểu tượng ấy.\n⚠ (Miền 4: An toàn) Biểu tượng hoà bình được nhiều tác giả sử dụng nên HS học cách dùng biểu tượng chứ không sao chép nguyên tác phẩm của một tác giả cụ thể; mọi hình tham khảo đều phải ghi tên tác giả.","hs":"- HS giải thích được ý nghĩa của một biểu tượng hoà bình trong mĩ thuật.\n- HS phân biệt được việc học cách dùng biểu tượng với việc chép tác phẩm."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 1 - Quan sát, nhận biết"},
{"lop":5,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện chủ đề thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS thiết kế và tự kiểm tra được bố cục, cỡ chữ của tranh cổ động.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề vì một thế giới hoà bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 5 (khai thác nội dung chủ đề vì một thế giới hoà bình).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS thiết kế bố cục tranh cổ động hoà bình trên phần mềm trình chiếu: đặt khối hình chính, chọn cỡ chữ khẩu hiệu, thử hai phương án màu nền, sau đó thu nhỏ trang chiếu để kiểm tra khẩu hiệu còn đọc được từ xa hay không.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS chỉnh lại bố cục và cỡ chữ dựa trên kết quả tự kiểm tra rồi thể hiện tranh bằng chất liệu thật.\n⚠ (Miền 4: An toàn) Khẩu hiệu do HS tự nghĩ, nếu mượn một câu đã có thì phải ghi rõ câu ấy của ai; lưu tệp vào thư mục của mình và không sửa tệp của bạn.","hs":"- HS thiết kế và tự kiểm tra được bố cục, cỡ chữ của tranh cổ động.\n- HS chỉnh sửa được sản phẩm dựa trên kết quả tự kiểm tra."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":5,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện nội dung chủ đề theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt, không gian để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo và dấu ấn cá nhân trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề vì một thế giới hoà bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (thực hành, sáng tạo sản phẩm).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- GV cho HS xem lại một số sản phẩm mẫu và nhắc lại yêu cầu của chủ đề (SGK Mĩ thuật 5).\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành.","hs":"- HS quan sát sản phẩm mẫu.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- GV tổ chức cho HS thực hành tạo sản phẩm mĩ thuật thể hiện chủ đề vì một thế giới hoà bình (cá nhân hoặc nhóm 2-4 HS).\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng chất liệu, vật liệu tái sử dụng hợp lí, an toàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình.\n- HS trao đổi, giúp đỡ nhau trong nhóm."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (thực hành, sáng tạo sản phẩm).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 3 - Thực hành, sáng tạo"},
{"lop":5,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Chủ đề 8: Vì một thế giới hoà bình (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình và của bạn.\n- Phân tích được vẻ đẹp, ý nghĩa của sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu, nhận xét sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- Yêu hoà bình, có ý thức chia sẻ, thân thiện với mọi người.\n- Chăm chỉ, nhân ái, có trách nhiệm với cộng đồng.\n4. Tích hợp\n- Năng lực số 2.2 CB2 (Chia sẻ thông tin qua công nghệ số): HS giới thiệu được tranh cổ động của mình với thông điệp rõ ràng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 5 (Kết nối tri thức với cuộc sống); hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; máy tính, máy chiếu và học liệu số; công cụ vẽ/thiết kế số đơn giản (ứng dụng vẽ trên máy tính, bảng tương tác…).\n- Học sinh: SGK Mĩ thuật 5, Vở bài tập Mĩ thuật 5; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, đất nặn, vật liệu tái sử dụng (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến chủ đề vì một thế giới hoà bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận và vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS hoàn thiện, sắp xếp sản phẩm để trưng bày (theo cá nhân/nhóm).\n- GV gợi ý cách giới thiệu, nêu ý tưởng và cảm nhận về sản phẩm.","hs":"- HS hoàn thiện, sắp xếp sản phẩm.\n- HS chuẩn bị lời giới thiệu về sản phẩm của mình."},{"ten":"3. Luyện tập - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm; gợi mở để HS phân tích, thảo luận về vẻ đẹp, ý nghĩa của sản phẩm.\n- GV nhận xét, đánh giá, ghi nhận sự tiến bộ và sáng tạo của HS.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét sản phẩm của mình và của bạn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV gợi ý HS vận dụng sản phẩm, kiến thức của chủ đề vì một thế giới hoà bình vào trang trí, làm đẹp góc học tập, lớp học hoặc cuộc sống.\n- GV hệ thống nội dung chủ đề, nhận xét tiết học, tuyên dương; dặn HS chuẩn bị cho chủ đề sau.","hs":"- HS nêu cách vận dụng sản phẩm vào cuộc sống.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp lập trang trưng bày tranh cổ động hoà bình kèm khẩu hiệu và giới thiệu trong buổi sinh hoạt dưới cờ; HS tập nói lời giới thiệu ngắn, rõ thông điệp.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi tên tác giả cho từng tranh và ghi nguồn cho mọi câu trích dẫn, hình ảnh tham khảo.\n⚠ (Miền 4: An toàn) Thông điệp hoà bình phải rõ ràng, không dùng hình ảnh bạo lực gây sợ hãi cho các em nhỏ hơn; chỉ chia sẻ trong nhà trường, đăng rộng hơn phải được nhà trường đồng ý.","hs":"- HS giới thiệu được tranh cổ động của mình với thông điệp rõ ràng.\n- HS ghi đủ tên tác giả và nguồn trên sản phẩm chung."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Chủ đề 8, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":5,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"Kiểm tra, đánh giá cuối năm học","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong năm để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình phù hợp nội dung; có ý tưởng và dấu ấn cá nhân.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.","dodung":"- Giáo viên: yêu cầu thực hành, tiêu chí đánh giá; thiết bị trình chiếu học liệu số.\n- Học sinh: đồ dùng học tập môn Mĩ thuật, giấy vẽ, màu vẽ, chất liệu đã chuẩn bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết kiểm tra, đánh giá cuối năm học.\n- GV công bố yêu cầu và tiêu chí đánh giá sản phẩm.","hs":"- HS lắng nghe, nắm yêu cầu và tiêu chí."},{"ten":"2. Thực hành, kiểm tra","gv":"- GV tổ chức cho HS làm bài thực hành: tạo một sản phẩm mĩ thuật theo chủ đề đã học trong năm.\n- GV bao quát lớp, hỗ trợ khi cần, bảo đảm HS làm bài độc lập.","hs":"- HS thực hành tạo sản phẩm theo yêu cầu.\n- HS vận dụng kiến thức, kĩ năng đã học cả năm."},{"ten":"3. Trưng bày, đánh giá","gv":"- GV tổ chức cho HS trưng bày, giới thiệu sản phẩm.\n- GV nhận xét, đánh giá theo tiêu chí; ghi nhận sự tiến bộ của HS trong năm học.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS tự đánh giá và nhận xét sản phẩm của bạn."},{"ten":"4. Vận dụng - Dặn dò","gv":"- GV tổng kết tiết kiểm tra, tuyên dương HS.\n- GV dặn dò chuẩn bị cho tiết trưng bày sản phẩm cuối năm.","hs":"- HS lắng nghe, ghi nhớ và chuẩn bị cho tiết trưng bày cuối năm."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Kiểm tra, đánh giá cuối năm học"},
{"lop":5,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"Trưng bày sản phẩm cuối năm và tổng kết năm học","yccd":"1. Năng lực mĩ thuật\n- Lựa chọn, sắp xếp và trưng bày được sản phẩm mĩ thuật tiêu biểu của cả năm học.\n- Giới thiệu, phân tích và nêu được cảm nhận về sản phẩm theo yếu tố, nguyên lí tạo hình.\n- Biết vận dụng kết quả học tập vào trang trí, làm đẹp lớp học và cuộc sống.\n2. Năng lực chung\n- Giao tiếp và hợp tác; giải quyết vấn đề và sáng tạo khi tổ chức trưng bày.\n3. Phẩm chất\n- Yêu thích môn học, trân trọng thành quả lao động; tự tin, đoàn kết, có trách nhiệm.\n4. Tích hợp\n- Năng lực số 3.2 CB2 (Tích hợp và tinh chỉnh nội dung số): HS tham gia dựng và hoàn thiện triển lãm số cuối năm của lớp.","dodung":"- Giáo viên: không gian trưng bày, tiêu chí đánh giá; thiết bị trình chiếu học liệu số.\n- Học sinh: các sản phẩm mĩ thuật đã thực hiện trong năm; đồ dùng để trang trí, sắp xếp trưng bày.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, nêu mục đích tiết trưng bày sản phẩm và tổng kết năm học.\n- GV tạo không khí vui tươi, khích lệ HS.","hs":"- HS lắng nghe, hào hứng tham gia."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS lựa chọn, sắp xếp sản phẩm tiêu biểu của cả năm theo nhóm/chủ đề.\n- GV gợi ý cách trang trí không gian trưng bày đẹp mắt, khoa học.","hs":"- HS lựa chọn, sắp xếp và trang trí sản phẩm.\n- HS chuẩn bị lời giới thiệu cho khu trưng bày."},{"ten":"3. Luyện tập - Trưng bày, giới thiệu","gv":"- GV tổ chức cho HS trưng bày, giới thiệu và thuyết trình về sản phẩm.\n- GV cùng HS thảo luận, bình chọn sản phẩm ấn tượng; nhận xét, đánh giá.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS thảo luận, nhận xét, bình chọn sản phẩm yêu thích."},{"ten":"4. Vận dụng - Tổng kết","gv":"- GV tổng kết năm học, tuyên dương HS có nhiều cố gắng và sáng tạo.\n- GV gợi ý HS tiếp tục vẽ, sáng tạo và làm đẹp cuộc sống trong dịp hè.","hs":"- HS nêu cảm nghĩ về môn học.\n- HS lắng nghe, ghi nhớ và có ý thức tiếp tục sáng tạo mĩ thuật."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS cùng nhau dựng triển lãm số cuối cấp tiểu học: chọn sản phẩm tiêu biểu của cả năm, sắp xếp theo chủ đề, viết lời mở đầu cho triển lãm và chú thích cho từng tác phẩm.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS phân công vai trò người dựng trang, người viết chú thích, người thuyết minh; mỗi nhóm báo cáo phần việc của mình và góp ý cho nhóm bạn.\n⚠ (Miền 4: An toàn) Triển lãm ghi đủ tên tác giả và nguồn tư liệu; chỉ ghi tên và lớp, không đưa số điện thoại, địa chỉ của HS; muốn đăng lên trang của trường phải được nhà trường và cha mẹ đồng ý.","hs":"- HS tham gia dựng và hoàn thiện triển lãm số cuối năm của lớp.\n- HS nhận và hoàn thành được vai trò của mình trong nhóm, góp ý cho nhóm bạn."}],"status":"checked","source":"KHBD Mĩ thuật 5 KNTT (Bút Xanh) - Trưng bày sản phẩm cuối năm và tổng kết năm học"}
];
